import { TextSelection } from '@tiptap/pm/state'
import { useValues } from 'kea'
import { useEffect, useState } from 'react'
import { createPortal } from 'react-dom'

import { IconArrowDown, IconArrowLeft, IconArrowRight, IconArrowUp, IconTrash } from '@posthog/icons'
import { LemonMenu, LemonMenuItems } from '@posthog/lemon-ui'

import { richContentEditorLogic } from 'lib/components/RichContentEditor/richContentEditorLogic'
import { IconDragHandle } from 'lib/lemon-ui/icons'

type TableMenuKind = 'row' | 'column'

// Width/height of the strip between the table edge and the handles. The invisible wrapper spans this
// strip (plus a small overlap into the table) so moving the cursor from a cell to a handle never
// leaves the hover area and the handles don't flicker.
const HANDLE_GUTTER = 20
const HANDLE_OVERLAP = 4

export function TableMenu(): JSX.Element | null {
    const { ttEditor } = useValues(richContentEditorLogic)
    const [hoveredCell, setHoveredCell] = useState<HTMLTableCellElement | null>(null)
    const [openMenu, setOpenMenu] = useState<TableMenuKind | null>(null)

    useEffect(() => {
        if (!ttEditor || openMenu) {
            // While a menu is open the handles stay pinned to the cell the menu was opened from
            return
        }

        const editorDom = ttEditor.view.dom

        const onMouseMove = (e: MouseEvent): void => {
            const target = e.target as HTMLElement | null
            if (target?.closest('.NotebookTableMenu__handle-wrapper')) {
                return
            }
            const cell = target?.closest<HTMLTableCellElement>('td, th') ?? null
            setHoveredCell(cell && editorDom.contains(cell) ? cell : null)
        }
        const onScroll = (): void => setHoveredCell(null)

        document.addEventListener('mousemove', onMouseMove)
        window.addEventListener('scroll', onScroll, true)
        return () => {
            document.removeEventListener('mousemove', onMouseMove)
            window.removeEventListener('scroll', onScroll, true)
        }
    }, [ttEditor, openMenu])

    if (!ttEditor || !ttEditor.isEditable || !hoveredCell || !hoveredCell.isConnected) {
        return null
    }

    const row = hoveredCell.closest('tr')
    const table = hoveredCell.closest('table')
    if (!row || !table) {
        return null
    }

    const cellRect = hoveredCell.getBoundingClientRect()
    const rowRect = row.getBoundingClientRect()
    const tableRect = table.getBoundingClientRect()

    const runOnHoveredCell = (action: (chain: ReturnType<typeof ttEditor.chain>) => typeof chain): void => {
        // Actions operate on the selection, so move it into the hovered cell first
        const pos = ttEditor.view.posAtDOM(hoveredCell, 0)
        const chain = ttEditor
            .chain()
            .focus()
            .command(({ tr }) => {
                tr.setSelection(TextSelection.near(tr.doc.resolve(pos)))
                return true
            })
        action(chain).run()
        setOpenMenu(null)
        setHoveredCell(null)
    }

    const deleteTableSection = {
        items: [
            {
                label: 'Delete table',
                icon: <IconTrash />,
                status: 'danger' as const,
                onClick: () => runOnHoveredCell((chain) => chain.deleteTable()),
            },
        ],
    }

    const rowItems: LemonMenuItems = [
        {
            items: [
